      double a2 = ( ( ( d1 * h2 ) - ( d2 * h1 ) ) / ( ( h1 * h2 ) * ( h1 - h2 ) ) ) ;
      double x = ( ( - 2 * a0 ) / ( a1 + abs ( sqrt ( a1 * a1 - 4 * a0 * a2 ) ) ) ) ;
      double y = ( ( - 2 * a0 ) / ( a1 - abs ( sqrt ( a1 * a1 - 4 * a0 * a2 ) ) ) ) ;
      if ( x >= y ) res = x + c ;
      else res = y + c ;
      double m = res * 100 ;
      double n = c * 100 ;
      m = floor ( m ) ;
      n = floor ( n ) ;
      if ( m == n ) break ;
      a = b ;
      b = c ;
